32	async function notify(userId: string, title: string, body?: string, href?: string) {
33	  try {
34	    await db.notification.create({ data: { userId, title, body, href } });
35	  } catch (e) {
36	    console.error("[game-config] notify failed", e);
37	  }
38	}
