40	export async function gameConfigApply(job: Job): Promise<void> {
41	  const serverId = job.serverId;
42	  if (!serverId) throw new Error("game config: job has no serverId");
43	
44	  const server = await db.server.findUnique({
45	    where: { id: serverId },
46	    include: { osTemplate: true, gamePlan: true },
47	  });
48	  if (!server) throw new Error(`Server ${serverId} not found`);
49	
50	  const family = familyFor(server);
51	  const schema = schemaFor(family);
52	  if (!family || !schema) {
53	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
54	  }
55	
56	  const variant = server.gameVariant ?? schema.defaultVariant;
57	
58	  // MVP: simulate the apply (always, and explicitly under SANDBOX). We stamp a
59	  // small applied-marker alongside the existing values so the portal can show the
60	  // last-applied variant/time, then notify the user. No SSH, no VM mutation.
61	  // TODO(real apply): replace this block with the per-family SSH/RCON logic above
62	  // when !SANDBOX and the server is RUNNING with an IP/password.
63	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
64	  const marker = {
65	    _appliedVariant: variant,
66	    _appliedAt: new Date().toISOString(),
67	    _configVersion: GAME_CONFIG_VERSION,
68	    _sandbox: SANDBOX,
69	  };
70	
71	  await db.server.update({
72	    where: { id: server.id },
73	    data: { gameConfig: { ...existing, ...marker } as any },
74	  });
75	
76	  await notify(
77	    server.userId,
78	    `Game settings applied on ${server.hostname}`,
79	    `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
80	    `/dashboard/servers/${server.id}?tab=game settings`
81	  );
82	}
