240	// ----------------------------------------------------------------------------
241	// Typed operations (sandbox-aware)
242	// ----------------------------------------------------------------------------
243	
244	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
245	  if (SANDBOX) {
246	    const node = simResolve(server.id, path);
247	    if (!node) throw new Error("No such directory.");
248	    if (node.type !== "dir") throw new Error("Not a directory.");
249	    return Object.entries(node.children)
250	      .map(([name, child]) => ({
251	        name,
252	        type: child.type === "dir" ? "d" : "-",
253	        isDirectory: child.type === "dir",
254	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
255	        modifiedMs: child.mtime,
256	        mode: child.mode,
257	      }))
258	      .sort((a, b) =>
259	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
260	      );
261	  }
262	
263	  return withSftp(server, async (client) => {
264	    const list = await client.list(path);
265	    return list
266	      .map((e) => ({
267	        name: e.name,
268	        type: e.type,
269	        isDirectory: e.type === "d",
270	        size: e.size,
271	        modifiedMs: e.modifyTime,
272	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
273	        // mode — derive the octal permission bits from them.
274	        mode: rightsToMode(e.rights),
275	      }))
276	      .sort((a, b) =>
277	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
278	      );
279	  });
280	}
281	
282	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
283	  if (SANDBOX) {
284	    const node = simResolve(server.id, path);
285	    if (!node) throw new Error("No such file or directory.");
286	    return {
287	      isDirectory: node.type === "dir",
288	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
289	      modifiedMs: node.mtime,
290	      mode: node.mode,
291	    };
292	  }
293	
294	  return withSftp(server, async (client) => {
295	    const s = await client.stat(path);
296	    return {
297	      isDirectory: s.isDirectory,
298	      size: s.size,
299	      modifiedMs: s.modifyTime,
300	      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
301	    };
302	  });
303	}
