import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget } from "../lib/sftp";
import {
  familyFor,
  schemaFor,
  validateConfig,
  GAME_CONFIG_VERSION,
  type FamilySchema,
} from "../lib/game-config";
import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
import type { Job } from "@prisma/client";

/**
 * GAME_CONFIG handler — apply a game server's customization (variant + settings).
 *
 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there:
 *   GAME_CONFIG: gameConfigApply,
 *
 * Ownership + validation happen at enqueue time (lib/actions-game-config.ts), so
 * this handler trusts `Server.gameVariant` / `Server.gameConfig`.
 *
 * TWO PATHS:
 *  - DEFAULT (simulation): records an "applied" marker on `Server.gameConfig` and
 *    notifies the user. No SSH, no VM mutation. This runs under SANDBOX and, in
 *    production, whenever the real path is NOT explicitly enabled. It keeps the
 *    portal flow (save → job → "applied" notification) working end to end.
 *
 *  - REAL (gated): actually pushes the settings to the live game server over SSH.
 *    Runs ONLY when `!SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1"`. It is
 *    deliberately non-destructive (read-modify-write for key=value files; never
 *    clobbers a config it can't find/parse) and fully wrapped in try/catch so a
 *    failure notifies the user but never crashes the worker.
 *
 * Enable the real path only once the per-family config paths / service names below
 * have been confirmed for the actual game-server images.
 */

/** True only when the operator has explicitly opted into real (non-sandbox) apply. */
const REAL_APPLY_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1";

const CONNECT_TIMEOUT_MS = 15_000;
const EXEC_TIMEOUT_MS = 30_000;

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-config] notify failed", e);
  }
}

export async function gameConfigApply(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game config: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
  }

  const variant = server.gameVariant ?? schema.defaultVariant;

  // -------------------------------------------------------------------------
  // DEFAULT PATH — simulation (unchanged). Runs under SANDBOX and whenever the
  // real path is not explicitly enabled. We stamp a small applied-marker
  // alongside the existing values so the portal can show the last-applied
  // variant/time, then notify the user. No SSH, no VM mutation.
  // -------------------------------------------------------------------------
  if (!REAL_APPLY_ENABLED) {
    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
    const marker = {
      _appliedVariant: variant,
      _appliedAt: new Date().toISOString(),
      _configVersion: GAME_CONFIG_VERSION,
      _sandbox: SANDBOX,
    };

    await db.server.update({
      where: { id: server.id },
      data: { gameConfig: { ...existing, ...marker } as any },
    });

    await notify(
      server.userId,
      `Game settings applied on ${server.hostname}`,
      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
      `/dashboard/servers/${server.id}?tab=game settings`
    );
    return;
  }

  // -------------------------------------------------------------------------
  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
  // a failure notifies the user but never throws out of the handler.
  // -------------------------------------------------------------------------
  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const valid = validateConfig(family, existing);
  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
  const values = valid.ok ? valid.values : {};

  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
  try {
    outcome = await applyRealConfig(server, family, values);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
  }

  // Always record the applied-marker (even on partial/soft failure) so the portal
  // reflects the attempt, and note whether the real push succeeded.
  const marker = {
    _appliedVariant: variant,
    _appliedAt: new Date().toISOString(),
    _configVersion: GAME_CONFIG_VERSION,
    _sandbox: SANDBOX,
    _real: true,
    _realOk: outcome.ok,
  };
  try {
    await db.server.update({
      where: { id: server.id },
      data: { gameConfig: { ...existing, ...marker } as any },
    });
  } catch (e) {
    console.error("[game-config] marker update failed", e);
  }

  const detail = [...outcome.applied, ...outcome.notes].join(" ");
  await notify(
    server.userId,
    outcome.ok
      ? `Game settings applied on ${server.hostname}`
      : `Game settings partially applied on ${server.hostname}`,
    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
    `/dashboard/servers/${server.id}?tab=game settings`
  );
}

// ===========================================================================
// Real apply — per-family rendering + SSH transport
// ===========================================================================

type Values = Record<string, string | number | boolean>;
type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };

/** The minimal Server shape the real path needs to open an SSH connection. */
type SshServer = {
  id: string;
  rootPassword: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
};

/**
 * Connect to the game-server VM (host/port derived exactly like the file manager,
 * user "root", password `rootPassword`), run `fn`, and always close the session.
 */
function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    const target = connectionTarget(server as any);
    if (!target) {
      reject(new Error("server is not reachable yet — connection details are pending"));
      return;
    }
    if (!server.rootPassword) {
      reject(new Error("server has no root password set"));
      return;
    }

    const conn = new Client();
    let settled = false;
    const finish = (err: Error | null, val?: T) => {
      if (settled) return;
      settled = true;
      try {
        conn.end();
      } catch {
        /* best-effort */
      }
      if (err) reject(err);
      else resolve(val as T);
    };

    conn.on("ready", () => {
      conn.sftp((err, sftp) => {
        if (err) return finish(err);
        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
      });
    });
    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
    conn.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password: server.rootPassword,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
  });
}

/** Read a remote text file, or null if it does not exist. */
function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
  return new Promise((resolve, reject) => {
    sftp.readFile(path, (err, data) => {
      if (err) {
        // ENOENT / no such file → null; anything else is a real error.
        const code = (err as NodeJS.ErrnoException).code;
        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
          return resolve(null);
        }
        return reject(err);
      }
      resolve(data.toString("utf8"));
    });
  });
}

/** Write a remote text file (overwrites). */
function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
  return new Promise((resolve, reject) => {
    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
  });
}

/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
      }, EXEC_TIMEOUT_MS);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/**
 * Locate the first existing path: try explicit candidates via `test -f`, then a
 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
 * Non-destructive — only reads.
 */
async function remoteLocate(
  conn: Client,
  candidates: string[],
  findRoots: string[],
  findName: string
): Promise<string | null> {
  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
  const findExpr = findRoots.length
    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
    : "true";
  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
  return hit ?? null;
}

/** Escape a value for single-quoted shell use. */
function shq(s: string): string {
  return s.replace(/'/g, "'\\''");
}

/** Dispatch to the correct family renderer. */
async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
  return withSsh(server, async (conn, sftp) => {
    switch (family) {
      case "minecraft":
        return applyMinecraft(conn, sftp, values);
      case "rust":
        return applyRust(conn, sftp, values);
      case "valheim":
        return applyValheim(conn, sftp, values);
      case "cs2":
        return applyCs2(conn, sftp, values);
      case "palworld":
        return applyPalworld(conn, sftp, values);
      default:
        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
    }
  });
}

// ---------------------------------------------------------------------------
// key=value file helpers (server.properties)
// ---------------------------------------------------------------------------

/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
function updateKeyValue(content: string, updates: Record<string, string>): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
    const eq = lines[i].indexOf("=");
    if (eq < 0) continue;
    const key = lines[i].slice(0, eq).trim();
    if (Object.prototype.hasOwnProperty.call(updates, key)) {
      lines[i] = `${key}=${updates[key]}`;
      seen.add(key);
    }
  }
  for (const k of Object.keys(updates)) {
    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
  }
  return lines.join("\n");
}

/** Read a `key=value` file into a map (comments/blank lines ignored). */
function parseKeyValue(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
    const eq = line.indexOf("=");
    if (eq < 0) continue;
    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
  }
  return out;
}

// ---------------------------------------------------------------------------
// space-separated convar/cvar helpers (rust server.cfg, cs2 server.cfg)
// ---------------------------------------------------------------------------

/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
function updateConvars(content: string, updates: Record<string, string>): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim();
    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
    const sp = t.search(/\s/);
    const key = sp < 0 ? t : t.slice(0, sp);
    if (Object.prototype.hasOwnProperty.call(updates, key)) {
      lines[i] = `${key} ${updates[key]}`;
      seen.add(key);
    }
  }
  for (const k of Object.keys(updates)) {
    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
  }
  return lines.join("\n");
}

const bool = (v: unknown) => (v === true || v === "true" || v === "on" ? "true" : "false");

// ---------------------------------------------------------------------------
// Minecraft → server.properties (key=value)
// ---------------------------------------------------------------------------

async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  // TODO(paths): confirm the actual install dir/service name for the Minecraft
  // image. These candidates cover the common layouts; if none match we soft-fail
  // rather than create a stray server.properties in the wrong place.
  const path = await remoteLocate(
    conn,
    [
      "/opt/minecraft/server.properties",
      "/srv/minecraft/server.properties",
      "/home/minecraft/server.properties",
      "/minecraft/server.properties",
      "/root/minecraft/server.properties",
    ],
    ["/opt", "/srv", "/home"],
    "server.properties"
  );
  if (!path) {
    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
  }

  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
  }

  // server.properties keys map 1:1 to the schema field keys.
  const updates: Record<string, string> = {};
  for (const [key, val] of Object.entries(v)) {
    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
  }
  const next = updateKeyValue(existing, updates);
  await sftpWrite(sftp, path, next);

  const notes: string[] = [];
  // Best-effort live push via RCON for the live-editable fields; otherwise note a
  // restart. Wrapped so RCON problems never fail the apply.
  try {
    await tryMinecraftRcon(conn, next, v, notes);
  } catch (e) {
    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
    console.error("[game-config] minecraft rcon error", e);
  }

  return {
    ok: true,
    applied: [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`],
    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
  };
}

/**
 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
 * on the box, pushes the live-editable settings. Anything missing → note a restart.
 */
async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
  const kv = parseKeyValue(props);
  const enabled = kv["enable-rcon"] === "true";
  const password = kv["rcon.password"] ?? "";
  const port = kv["rcon.port"] || "25575";
  if (!enabled || !password) {
    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
    return;
  }
  const which = await execRemote(conn, "command -v mcrcon || true");
  if (!which.stdout.trim()) {
    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
    return;
  }

  // A conservative set of safe live commands. TODO(rcon): expand once the exact
  // runtime command set is verified for the target Minecraft build.
  const cmds: string[] = [];
  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
  if (cmds.length === 0) return;

  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
  const res = await execRemote(
    conn,
    `mcrcon -H 127.0.0.1 -P ${shq(port)} -p '${shq(password)}' ${quoted} 2>&1 || true`
  );
  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
}

// ---------------------------------------------------------------------------
// Rust → server.cfg (server.<convar> value)
// ---------------------------------------------------------------------------

async function applyRust(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  // Rust reads server.cfg from <identity>/cfg/server.cfg — the identity dir is
  // deployment-specific, so we locate it rather than guessing.
  // TODO(paths): confirm the server identity/install path for the Rust image.
  const path = await remoteLocate(
    conn,
    ["/opt/rust/server/rustserver/cfg/server.cfg", "/opt/rust/server/cfg/server.cfg", "/home/rust/server/rustserver/cfg/server.cfg"],
    ["/opt/rust", "/home/rust", "/home/steam", "/opt"],
    "server.cfg"
  );
  if (!path) {
    return { ok: false, applied: [], notes: ["Could not locate Rust server.cfg — nothing was changed."] };
  }
  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`server.cfg disappeared at ${path} — nothing was changed.`] };
  }

  // Field keys map to `server.<key>` convars; strings are quoted.
  const updates: Record<string, string> = {};
  for (const [key, val] of Object.entries(v)) {
    const convar = `server.${key}`;
    if (typeof val === "boolean") updates[convar] = bool(val);
    else if (typeof val === "number") updates[convar] = String(val);
    else updates[convar] = `"${String(val).replace(/"/g, '\\"')}"`;
  }
  const next = updateConvars(existing, updates);
  await sftpWrite(sftp, path, next);

  // Rust RCON is a WebSocket (rcon.web) protocol — not attempted here.
  // TODO(rcon): push live convars (hostname/maxplayers/pve) via the Rust
  // WebSocket RCON if the server exposes it. For now note a restart/wipe.
  return {
    ok: true,
    applied: [`Wrote ${Object.keys(updates).length} convar(s) to ${path}.`],
    notes: ["Restart the server to apply. World-size/seed changes only take effect on the next map wipe."],
  };
}

// ---------------------------------------------------------------------------
// Valheim → launch args (mechanism deployment-specific)
// ---------------------------------------------------------------------------

async function applyValheim(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  // Valheim settings are launch args (-world/-preset/-public/-password), not a
  // config file, so the exact wiring depends on the start script / systemd unit.
  // TODO(valheim): point the start script/systemd unit at the args file we write
  // below (or template the unit directly). We deliberately do NOT rewrite the
  // start script here — that would risk clobbering a script we can't parse.
  const parts: string[] = [];
  if (v["world"] != null) parts.push(`-world "${String(v["world"]).replace(/"/g, "")}"`);
  if (v["preset"] != null) parts.push(`-preset ${String(v["preset"])}`);
  if (v["public"] != null) parts.push(`-public ${bool(v["public"]) === "true" ? "1" : "0"}`);
  if (v["password"] != null && String(v["password"]).length > 0) {
    parts.push(`-password "${String(v["password"]).replace(/"/g, "")}"`);
  }
  const args = parts.join(" ");

  // Find a Valheim install dir to drop the args file next to.
  const dir = await remoteLocate(
    conn,
    [],
    ["/opt/valheim", "/home/valheim", "/home/steam/valheim", "/opt"],
    "valheim_server.x86_64"
  );
  if (!dir) {
    return {
      ok: false,
      applied: [],
      notes: ["Could not locate the Valheim install — launch args were not written. Restart with the new args once the install path is known."],
    };
  }
  const targetDir = dir.replace(/\/[^/]*$/, "");
  const argsFile = `${targetDir}/nxeon-launch-args.txt`;
  await sftpWrite(sftp, argsFile, args + "\n");

  return {
    ok: true,
    applied: [`Wrote launch args to ${argsFile}.`],
    notes: ["Wire the start script/systemd unit to source this file, then restart the server. Password/world changes require a restart."],
  };
}

// ---------------------------------------------------------------------------
// CS2 → server.cfg (cvars) + launch-only notes
// ---------------------------------------------------------------------------

const CS2_GAME_MODE: Record<string, { game_type: string; game_mode: string }> = {
  competitive: { game_type: "0", game_mode: "1" },
  wingman: { game_type: "0", game_mode: "2" },
  casual: { game_type: "0", game_mode: "0" },
  deathmatch: { game_type: "1", game_mode: "2" },
  custom: { game_type: "3", game_mode: "0" },
};

async function applyCs2(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  // TODO(paths): confirm the CS2 dedicated-server cfg dir (…/game/csgo/cfg).
  const path = await remoteLocate(
    conn,
    [
      "/opt/cs2/game/csgo/cfg/server.cfg",
      "/home/cs2/cs2/game/csgo/cfg/server.cfg",
      "/home/steam/cs2/game/csgo/cfg/server.cfg",
    ],
    ["/opt/cs2", "/home/cs2", "/home/steam", "/opt"],
    "server.cfg"
  );
  if (!path) {
    return { ok: false, applied: [], notes: ["Could not locate CS2 server.cfg — nothing was changed."] };
  }
  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`server.cfg disappeared at ${path} — nothing was changed.`] };
  }

  const updates: Record<string, string> = {};
  const notes: string[] = [];

  if (v["maxrounds"] != null) updates["mp_maxrounds"] = String(v["maxrounds"]);
  if (v["bots"] != null) updates["bot_quota"] = bool(v["bots"]) === "true" ? "10" : "0";
  if (v["game_mode"] != null) {
    const gm = CS2_GAME_MODE[String(v["game_mode"])];
    if (gm) {
      updates["game_type"] = gm.game_type;
      updates["game_mode"] = gm.game_mode;
      notes.push("game_type/game_mode take effect on next map load / relaunch.");
    }
  }
  if (v["tickrate"] != null) {
    // -tickrate is a launch parameter, not a cvar — cannot be set from server.cfg.
    notes.push(`Tickrate ${String(v["tickrate"])} requires relaunching CS2 with -tickrate ${String(v["tickrate"])}.`);
  }

  const next = updateConvars(existing, updates);
  await sftpWrite(sftp, path, next);

  // TODO(rcon): CS2 supports source RCON — mp_maxrounds/bot_quota could be pushed
  // live if the rcon_password is known. Not attempted here (credentials unknown).
  return {
    ok: true,
    applied: [`Wrote ${Object.keys(updates).length} cvar(s) to ${path}.`],
    notes: notes.length ? notes : ["Reload the map or exec server.cfg for the new cvars to take effect."],
  };
}

// ---------------------------------------------------------------------------
// Palworld → PalWorldSettings.ini (single OptionSettings=(...) line)
// ---------------------------------------------------------------------------

/** Split a comma-separated OptionSettings body at top level (respecting quotes). */
function splitTopLevel(s: string): string[] {
  const out: string[] = [];
  let cur = "";
  let inQuote = false;
  for (const ch of s) {
    if (ch === '"') inQuote = !inQuote;
    if (ch === "," && !inQuote) {
      out.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  if (cur.length) out.push(cur);
  return out;
}

/**
 * Update keys inside the `OptionSettings=(...)` block, preserving the section
 * header, all other keys, and quoting. Returns null if the block can't be parsed
 * (so the caller soft-fails instead of clobbering the file).
 */
function updatePalworld(content: string, updates: Record<string, string>): string | null {
  const idx = content.indexOf("OptionSettings=(");
  if (idx < 0) return null;
  const open = content.indexOf("(", idx);
  const close = content.indexOf(")", open);
  if (open < 0 || close < 0) return null;

  const inner = content.slice(open + 1, close);
  const pairs = splitTopLevel(inner);
  const order: string[] = [];
  const map = new Map<string, string>();
  for (const p of pairs) {
    const eq = p.indexOf("=");
    if (eq < 0) continue;
    const k = p.slice(0, eq).trim();
    order.push(k);
    map.set(k, p.slice(eq + 1));
  }
  for (const [k, val] of Object.entries(updates)) {
    if (!map.has(k)) order.push(k);
    map.set(k, val);
  }
  const rebuilt = order.map((k) => `${k}=${map.get(k)}`).join(",");
  return content.slice(0, open + 1) + rebuilt + content.slice(close);
}

async function applyPalworld(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  // TODO(paths): confirm the PalServer install root for the Palworld image.
  const path = await remoteLocate(
    conn,
    [
      "/opt/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
      "/home/steam/Steam/steamapps/common/PalServer/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
      "/home/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
    ],
    ["/opt/palworld", "/home/steam", "/home/palworld", "/opt"],
    "PalWorldSettings.ini"
  );
  if (!path) {
    return { ok: false, applied: [], notes: ["Could not locate PalWorldSettings.ini — nothing was changed."] };
  }
  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`PalWorldSettings.ini disappeared at ${path} — nothing was changed.`] };
  }

  // Schema field keys → PalWorldSettings OptionSettings keys.
  const updates: Record<string, string> = {};
  if (v["difficulty"] != null) updates["Difficulty"] = String(v["difficulty"]);
  if (v["death-penalty"] != null) updates["DeathPenalty"] = String(v["death-penalty"]);
  if (v["pvp"] != null) updates["bEnablePlayerToPlayerDamage"] = bool(v["pvp"]) === "true" ? "True" : "False";
  if (v["exp-rate"] != null) {
    const n = Number(v["exp-rate"]);
    updates["ExpRate"] = Number.isFinite(n) ? n.toFixed(6) : String(v["exp-rate"]);
  }
  if (v["player-caps"] != null) updates["ServerPlayerMaxNum"] = String(v["player-caps"]);

  const next = updatePalworld(existing, updates);
  if (next == null) {
    return {
      ok: false,
      applied: [],
      notes: [`Could not parse the OptionSettings line in ${path} — left untouched to avoid corrupting it.`],
    };
  }
  await sftpWrite(sftp, path, next);

  // Palworld has no live-editable path for these — a restart is always required.
  return {
    ok: true,
    applied: [`Updated ${Object.keys(updates).length} setting(s) in ${path}.`],
    notes: ["Restart the Palworld server for the new settings to take effect."],
  };
}

